}

class MasukViewModel : ViewModel() {
    private val _state = MutableStateFlow(MasukUiState())
    val state: StateFlow<MasukUiState> = _state.asStateFlow()

    fun ubahEmail(e: String) = _state.update { it.copy(email = e.trim(), pesanError = null) }
    fun ubahSandi(s: String) = _state.update { it.copy(sandi = s, pesanError = null) }
    fun kirim() {
        if (!_state.value.bisaKirim) _state.update { it.copy(pesanError = "Email atau sandi belum valid") }
    }
}

class JadwalViewModel(private val ambilJadwal: suspend () -> List<String>) : ViewModel() {
    private val _jadwal = MutableStateFlow<List<String>>(emptyList())
    val jadwal: StateFlow<List<String>> = _jadwal.asStateFlow()
    private val _memuat = MutableStateFlow(false)
